package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructParametricType_TriageGen2Test {

    @Test
    public void testConstructParametricType_SingleParameter() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test List<String>
        JavaType result = typeFactory.constructParametricType(List.class, String.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(1, result.getTypeParameters().length);
        Assert.assertEquals(String.class, result.constructType(result.getTypeParameters()[0].getRawClass()).getRawClass());
    }

    @Test
    public void testConstructParametricType_MultipleParameters() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test Map<String, Integer>
        JavaType result = typeFactory.constructParametricType(Map.class, String.class, Integer.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(Map.class, result.getRawClass());
        Assert.assertEquals(2, result.getTypeParameters().length);

        // Verify key type
        JavaType keyType = result.constructType(result.getTypeParameters()[0].getRawClass());
        Assert.assertEquals(String.class, keyType.getRawClass());

        // Verify value type
        JavaType valueType = result.constructType(result.getTypeParameters()[1].getRawClass());
        Assert.assertEquals(Integer.class, valueType.getRawClass());
    }

    @Test
    public void testConstructParametricType_NoParameters() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test a non-generic class or providing no params to a generic one
        // Note: constructParametricType(Class, Class...) will call constructParametricType(Class, JavaType...)
        JavaType result = typeFactory.constructParametricType(ArrayList.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(ArrayList.class, result.getRawClass());
        Assert.assertEquals(0, result.getTypeParameters().length);
    }

    @Test
    public void testConstructParametricType_WithCustomClasses() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        class CustomContainer<T, U> {}

        JavaType result = typeFactory.constructParametricType(CustomContainer.class, Double.class, Boolean.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(CustomContainer.class, result.getRawClass());
        Assert.assertEquals(2, result.getTypeParameters().length);

        JavaType firstParam = result.constructType(result.getTypeParameters()[0].getRawClass());
        Assert.assertEquals(Double.class, firstParam.getRawClass());

        JavaType secondParam = result.constructType(result.getTypeParameters()[1].getRawClass());
        Assert.assertEquals(Boolean.class, secondParam.getRawClass());
    }

    @Test
    public void testConstructParametricType_NestedGenerics() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test List<List<String>>
        JavaType innerType = typeFactory.constructParametricType(List.class, String.class);
        JavaType outerType = typeFactory.constructParametricType(List.class, innerType.getRawClass());

        // Since the method signature takes Class<?>... parameterClasses, 
        // we can't pass a JavaType directly into the varargs version of this specific method.
        // We must use the version that accepts JavaType... if we want nesting via this specific method.
        // However, the method under test calls constructParametricType(parametrized, pt) where pt is JavaType[].

        // To test the logic branch of the method being tested:
        // It converts Class<?> to JavaType via _fromClass and then calls the other overload.

        JavaType result = typeFactory.constructParametricType(List.class, String.class);
        Assert.assertEquals(String.class, result.constructType(result.getTypeParameters()[0].getRawClass()).getRawClass());
    }

    @Test
    public void testConstructParametricType_WithPrimitives() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test Map<Integer, Long> (using wrapper classes)
        JavaType result = typeFactory.constructParametricType(HashMap.class, Integer.class, Long.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(HashMap.class, result.getRawClass());
        Assert.assertEquals(Integer.class, result.constructType(result.getTypeParameters()[0].getRawClass()).getRawClass());
        Assert.assertEquals(Long.class, result.constructType(result.getTypeParameters()[1].getRawClass()).getRawClass());
    }
}
